import{LANDMARKS,point,inPolygon,nearest,distance}from'./navigation.mjs?v=courtyard-1.3';
import{createState,saveData,update,walk,upgrade,SAVE_KEY}from'./world.mjs?v=courtyard-1.3';
import{createRenderer}from'./renderer.mjs?v=courtyard-1.3';
import{attachMapInput}from'../map-input.mjs';
import{icon,plantArt}from'./icons.mjs?v=courtyard-1.3';
const $=id=>document.getElementById(id);let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE_KEY));}catch{}const state=createState(saved);let renderer,panelType=null,lastSave=0,lastHud=0,noticeTimer,arrival=null,debug=false;
const systems=[['master','掌门','master'],['build','营造','build'],['people','门人','people'],['heritage','传承','scroll'],['production','生产','produce'],['gate','山门','gate'],['outside','山外','outside'],['journal','纪事','scroll']];
$('systems').innerHTML=systems.map(([id,label,i])=>`<button data-system="${id}" title="${label}" aria-label="${label}">${icon(i)}<span>${label}</span></button>`).join('');$('settings').innerHTML=icon('gear');$('journal').innerHTML=icon('check');$('quest-icon').innerHTML=icon('book');
function notify(text,record=true){$('notice').textContent=text;$('notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').classList.remove('visible'),3800);if(record){state.logs.push({day:state.day,text});state.logs=state.logs.slice(-50);}save();}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(saveData(state)));$('save-status').textContent='已保存';}catch{$('save-status').textContent='未能保存';}}
const resourceLabels={jade:['灵玉','jade'],wood:['木材','wood'],stone:['石料','stone'],herb:['灵草','herb'],grain:['粮食','grain']};
function hud(){const colors={jade:'#a5d9b4',wood:'#c69f6e',stone:'#b7bdba',herb:'#afc884',grain:'#e6c788'};$('resources').innerHTML=Object.entries(resourceLabels).map(([k,[label,i]])=>`<span class="resource" title="${label}" aria-label="${label} ${state.resources[k]}"><span style="color:${colors[k]}">${icon(i)}</span><span>${state.resources[k]}</span></span>`).join('');$('calendar').textContent=`第${state.day}日 · 晴岚`;$('pause').textContent=state.paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',state.paused?'继续':'暂停');document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===state.speed));$('quest-text').textContent=state.quest?'札记已整理 · 药理初成':'整理母亲的药理札记';const a=state.actors[0];$('walk-status').textContent=`掌门${a.path.length?'行走中':'已停步'}；位置 ${a.x.toFixed(1)}, ${a.y.toFixed(1)}；寻路 ${state.metrics.routes} 次；越界 ${state.metrics.invalid} 次`;if(panelType==='settings')$('qa-stats').textContent=`寻路 ${state.metrics.routes} 次 · 道路越界 ${state.metrics.invalid} 次 · 边界拦截 ${state.metrics.blocked} 次`;}
function selected(){const item=LANDMARKS.find(l=>l.id===state.selected)||LANDMARKS[4],level=state.buildings[item.id].level;const detail={herbs:['照料中 · 陆知微',`灵草 +${3*level} / 每18息`],main:['掌门旧居 · 典籍存放',`修缮等级 ${level}`],meditation:['静修中 · 温苓','竹林清静，可研习传承'],workshop:['作业中 · 林伯',`木材 +${2*level} / 每18息`],works:['石料整理中',`石料 +${level} / 每18息`],kitchen:['照料中 · 青禾',`粮食 +${2*level} / 每18息`],gate:['山门开放 · 宋砚守院',`修缮等级 ${level}`]}[item.id];$('selection').innerHTML=`<div class="selected-top"><div class="plant-art">${item.id==='herbs'?plantArt:icon(item.id==='meditation'?'book':item.id==='workshop'?'wood':item.id==='kitchen'?'produce':'build')}</div><div><h2>${item.name}</h2><p>${detail[0]}</p><p>${detail[1]}</p></div></div><div class="selection-actions"><button data-action="details">${icon('info')}详情</button><button data-action="upgrade">${icon('up')}升级</button><button data-action="go">${icon('walk')}前往</button></div>`;}
function go(id){const l=LANDMARKS.find(x=>x.id===id);if(walk(state,state.actors[0],point(l.node))){arrival=l.name;renderer.mark(point(l.node));notify(`前往${l.name}，沿院路行走。`,false);closePanel();}else notify('此处尚未接通院路。',false);}
function closePanel(){panelType=null;$('panel').hidden=true;document.querySelectorAll('[data-system]').forEach(b=>b.classList.remove('active'));}
function action(text,act,extra=''){return`<button class="action" data-act="${act}" ${extra}>${text}</button>`;}
function openPanel(type){panelType=type;$('panel').hidden=false;document.querySelectorAll('[data-system]').forEach(b=>b.classList.toggle('active',b.dataset.system===type));const titles={master:'掌门 · 沈砚',build:'营造 · 山院居所',people:'门人 · 同行与照料',heritage:'传承 · 家门旧卷',production:'生产 · 山院供给',gate:'山门 · 出入有序',outside:'山外 · 出行准备',journal:'纪事 · 院中见闻',quest:'旧卷余温',details:LANDMARKS.find(l=>l.id===state.selected).name,settings:'设置与行走检查',help:'山院行走'};$('panel-title').textContent=titles[type];const body=$('panel-body');
if(type==='master')body.innerHTML=`<div class="person"><img class="portrait" src="${renderer.portrait(0)}" alt="沈砚"><div><strong>沈砚</strong><small>掌门 · 练气初境</small></div></div><p>旧院初复，尚有许多事等着你与门人一同完成。</p><h3>今日所行</h3><div class="keys"><span>沿石路行走</span><span>过桥登阶</span><span>照看药圃</span></div>${action('前往静台','go','data-id="meditation"')} ${action('返回主屋','go','data-id="main"')}<p class="muted">点击道路也可直接移动。人物不会在溪流、屋顶或山崖上行走。</p>`;
if(type==='build')body.innerHTML=LANDMARKS.map(l=>`<div class="row"><div><strong>${l.name}</strong><small>${state.buildings[l.id].level} 级 · ${l.desc}</small></div>${action('查看','select',`data-id="${l.id}"`)}</div>`).join('')+'<p class="muted">本场景沿山势固定建筑位置。修缮可提升产出；搬迁需要另行拆分建筑素材。</p>';
if(type==='people')body.innerHTML=state.actors.slice(1).map(a=>`<div class="row person"><img class="portrait" src="${renderer.portrait(a.variant)}" alt="${a.name}"><div class="person-text"><strong>${a.name}</strong><small>${a.role}${a.follow?' · 随掌门同行':''}</small></div><label><input type="checkbox" data-follow="${a.id}" ${a.follow?'checked':''} aria-label="${a.name}同行"> 同行</label></div>`).join('')+'<p class="muted">同行者会沿同一组院路追随掌门；身份与服饰在保存后保持一致。</p>';
if(type==='heritage')body.innerHTML=`${icon('scroll')}<h3>青囊药理 · 入门篇</h3><p>草木相生，药性随时令而转。母亲留下的札记，是重整山院的第一步。</p><p>研习需灵玉 20${state.quest?'':'，先完成「旧卷余温」'}。</p>${action(state.learned?'已研习':'研习药理','learn',state.learned?'disabled':'')}<p class="muted">研习后获得本场景的药理记事；此处展示传承交互原型。</p>`;
if(type==='production')body.innerHTML=`<p>门人每18息完成一轮照料。暂停时，生产与行走同时停止。</p>${[['herbs','灵草','herb',3],['workshop','木材','wood',2],['works','石料','stone',1],['kitchen','粮食','grain',2]].map(([id,name,key,n])=>`<div class="row"><div><strong>${name} · +${n*state.buildings[id].level}</strong><small>${LANDMARKS.find(l=>l.id===id).name} ${state.buildings[id].level} 级</small></div>${action('前往','go',`data-id="${id}"`)}</div>`).join('')}`;
if(type==='gate')body.innerHTML=`<h3>云岫山门</h3><p>石阶向下，便是远山与云海。今日由宋砚守院。</p><p>山门等级 ${state.buildings.gate.level} · 院门开放</p>${action('走到山门','go','data-id="gate"')} ${action('查看修缮','select','data-id="gate"')}`;
if(type==='outside')body.innerHTML=`<h3>备一份干粮</h3><p>门外诸境尚未开放。先备好行囊，再沿石阶走到山门。</p><p>准备需粮食 5，可换得行囊记事。</p>${action('准备行囊','pack')} ${action('前往山门','go','data-id="gate"')}<p class="muted">当前可操作范围为云岫别院这一处场景。</p>`;
if(type==='journal')body.innerHTML=state.logs.length?state.logs.slice().reverse().map(l=>`<div class="log"><time>第${l.day}日</time>${l.text}</div>`).join(''):'<p>竹影初动，院中尚无新事。去看看药圃吧。</p>';
if(type==='quest')body.innerHTML=`<h3>母亲的药理札记</h3><p>案上旧卷散落，纸页间还夹着晒干的白花。整理好札记，或许就能读懂药田里的草木。</p><p>完成后获得灵玉 15，并开放青囊药理研习。</p>${action(state.quest?'札记已整理':'整理札记','quest',state.quest?'disabled':'')} ${action('前往主屋','go','data-id="main"')}`;
if(type==='details'){const l=LANDMARKS.find(l=>l.id===state.selected),b=state.buildings[l.id];body.innerHTML=`<h3>${l.name} · ${b.level} 级</h3><p>${l.desc}</p><p>修缮需木材 ${b.wood*b.level}、石料 ${b.stone*b.level}。</p>${action('修缮升级','upgrade')} ${action('沿路前往','go',`data-id="${l.id}"`)}<p class="muted">${l.id==='herbs'?'药田分布在三层石台上，门人沿田埂行走。':'建筑位置依照原图固定，人物行走区域与建筑分开。'}</p>`;}
if(type==='settings')body.innerHTML=`<h3>行走显示</h3><label><input type="checkbox" id="debug-toggle" ${debug?'checked':''}> 显示道路与掌门路径</label><p id="qa-stats" class="muted"></p><h3>画面与保存</h3><p>场景完整呈现于横屏；竖屏可拖动画面。存档与正式游戏分开保存。</p>${action('立即保存','save')} ${action('操作帮助','help')}<p class="muted">场景版本 courtyard-1.3 · 绘景与角色素材为预渲染图像，行走、寻路、生产和 UI 为实时逻辑。</p>`;
if(type==='help')body.innerHTML=`<p class="help-note">点击石路：掌门前往。点击建筑或药田：查看详情，再选择「前往」。</p><div class="keys"><span>Esc 关闭面板</span><span>空格 暂停</span><span>1 / 2 / 4 调速</span></div><p>「门人」可选择同行者；「生产」查看产出；「升级」扣除木石并提升等级。</p><p>竖屏时可拖动画面。桥、台阶和田埂均有固定通路，点击溪流或山崖不会让人物直接穿过去。</p>`;
hud();}
function dispatch(act,id){if(act==='go')go(id||state.selected);if(act==='select'){state.selected=id;selected();openPanel('details');renderer.mark(point(LANDMARKS.find(l=>l.id===id).node));save();}if(act==='upgrade'){const result=upgrade(state,state.selected);notify(result.text);selected();hud();if(panelType==='details')openPanel('details');}if(act==='quest'&&!state.quest){state.quest=true;state.resources.jade+=15;notify('札记已整理，灵玉 +15。');openPanel('quest');hud();}if(act==='learn'&&!state.learned){if(!state.quest)notify('先整理母亲的药理札记。',false);else if(state.resources.jade<20)notify('研习需灵玉 20。',false);else{state.resources.jade-=20;state.learned=true;notify('研习青囊药理，草木之性初明。');openPanel('heritage');hud();}}if(act==='pack'){if(state.resources.grain<5)notify('干粮不足，需粮食 5。',false);else{state.resources.grain-=5;notify('备好干粮，可前往山门。');hud();}}if(act==='save'){save();notify('山院进度已保存。',false);}if(act==='help')openPanel('help');}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.system)openPanel(button.dataset.system);if(button.dataset.act)dispatch(button.dataset.act,button.dataset.id);if(button.dataset.action)dispatch(button.dataset.action==='details'?'select':button.dataset.action,state.selected);if(button.dataset.speed){state.speed=Number(button.dataset.speed);state.paused=false;hud();}if(button.id==='pause'){state.paused=!state.paused;hud();}if(button.id==='close-panel')closePanel();if(button.id==='settings')openPanel('settings');if(button.id==='journal')openPanel('journal');if(button.id==='quest')openPanel('quest');if(button.id==='guide')openPanel('help');});
document.addEventListener('change',e=>{if(e.target.dataset.follow){const a=state.actors.find(x=>x.id===e.target.dataset.follow);a.follow=e.target.checked;a.wait=0;if(!a.follow){walk(state,a,point(a.home));}notify(`${a.name}${a.follow?'随掌门同行':'返回院中照料'}。`);openPanel('people');}if(e.target.id==='debug-toggle'){debug=e.target.checked;renderer.setDebug(debug);}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Escape')closePanel();if(e.code==='Space'){e.preventDefault();state.paused=!state.paused;hud();}if(['1','2','4'].includes(e.key)){state.speed=Number(e.key);state.paused=false;hud();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('pagehide',save);
try{renderer=await createRenderer($('world'),state);attachMapInput($('world'),{pan:renderer.pan,onHover(){},onActivate(e){const p=renderer.worldPoint(e),actor=state.actors.find(a=>distance(a,p)<20);if(actor&&actor.id!=='master'){openPanel('people');return;}const l=LANDMARKS.find(l=>inPolygon(p,l.hit));if(l){state.selected=l.id;selected();renderer.mark(point(l.node));save();return;}const q=nearest(p);if(q.d>34){notify('这里不是院路。请点石路、桥面或田埂。',false);return;}if(walk(state,state.actors[0],p)){arrival='所选院路';renderer.mark(q);}else notify('此处无法通行。',false);},enabled:()=>$('panel').hidden});$('loading').hidden=true;selected();hud();let previous=performance.now();function frame(t){const dt=(t-previous)/1000;previous=t;update(state,dt,text=>notify(text));renderer.draw(t);if(arrival&&!state.actors[0].path.length){notify(`已到达${arrival}。`,false);arrival=null;save();}if(t-lastHud>500){hud();lastHud=t;}if(t-lastSave>5000){save();lastSave=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);if(!saved)notify('山院初醒。点击院路行走，点击建筑查看。',false);}catch(error){$('loading').textContent=`场景加载未完成：${error.message}。请刷新重试。`;console.error(error);}
